"use client"

import * as React from "react"
import * as ToggleGroupPrimitive from "@radix-ui/react-toggle-group"

import { cn } from "@/lib/utils"

/** Words held apart by standing hairlines. type="single" allows one held at a time; "multiple" allows any. */
function ToggleGroup({ className, ...props }: React.ComponentProps<typeof ToggleGroupPrimitive.Root>) {
  return <ToggleGroupPrimitive.Root data-slot="toggle-group" className={cn("db-toggles", className)} {...props} />
}

/** One word in the group. Wears the same fermata as a Toggle. */
function ToggleGroupItem({ className, ...props }: React.ComponentProps<typeof ToggleGroupPrimitive.Item>) {
  return <ToggleGroupPrimitive.Item data-slot="toggle-group-item" className={cn("db-toggle", className)} {...props} />
}

export { ToggleGroup, ToggleGroupItem }

@layer components {
  /* ── db-toggles ── toggle group: words held apart by standing hairlines */
  .db-toggles { display: inline-flex; flex-wrap: wrap; align-items: last baseline; row-gap: var(--db-space-3); }
  .db-toggles > .db-toggle + .db-toggle {
    --pad: var(--db-space-4);
    margin-inline-start: var(--db-space-4); padding-inline-start: var(--db-space-4);
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 calc(100% - 0.15em) / var(--db-hairline) 1.05em;
  }
  .db-toggles > .db-toggle + .db-toggle:is([dir="rtl"], [dir="rtl"] *) { background-position: 100% calc(100% - 0.15em); }
}
